'use client'

import * as React from 'react'

// `./tutorial-step` and `./segments` rather than `../<name>/<name>`: see the
// note in ./tutorial-step.ts. The installed layout is flat, so these are the
// paths that are correct for a consumer, and the shims make them correct here.
import { TutorialStep } from './tutorial-step'
import { Segments, type Segment } from './segments'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Onboarding, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './onboarding.css'

// And the shared rule sets, which carry the theme's action face and press
// gesture. The three controls apply `.gs-action-type` and `.gs-pressable`, and
// without this import a customer receives the file and the classes match
// nothing. See ./gamestage-primitives.css. GSUI-118.
import './gamestage-primitives.css'

/**
 * Onboarding: the sequence a player is walked through before they play.
 *
 * Specimen 3g. An illustration, a title, a line of explanation, the pager
 * saying where in the sequence this is, and a way forward with a way out
 * beside it.
 *
 * The step itself is a `tutorial-step` rather than a card written here, and the
 * pager is `segments` in its pager treatment, which is the same row of cells as
 * the round indicator and the quest's progress. Two components composed, none
 * reimplemented.
 *
 * The step the sequence is on is `data-gs-step` over `data-gs-max`, the same
 * pair progress uses, because "step 2 of 5" and "2 of 5 segments filled" are
 * the same idea. `data-gs-active` is not `data-gs-selected`: the player did not
 * pick this step. A finished sequence carries `data-gs-complete`, and one the
 * player skipped carries `data-gs-dismissed`, which is a state rather than an
 * unmount so a test can tell "closed by the player" from "never rendered".
 *
 * It performs nothing. It does not advance itself, remember that the player has
 * seen it, or decide the sequence is done. `onNext`, `onBack` and `onDismiss`
 * report the press and the host owns everything behind it.
 */

export interface OnboardingStep {
  /** The host's own id for this step, if it has one. */
  id?: string
  /** The step's heading. */
  title: string
  /** The line of explanation under it. */
  body?: React.ReactNode
  /** The illustration or animation this step leads with. */
  media?: React.ReactNode
}

export interface OnboardingProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Every step of the sequence, in order. */
  steps: OnboardingStep[]
  /** Which one the sequence is on, from 1. */
  step: number
  /** Finished. The host decides; the component never infers it from the step. */
  complete?: boolean
  /** The player closed it and it stays closed. */
  dismissed?: boolean
  /** Called on the way forward. Absent means this step has no next control. */
  onNext?: () => void
  /** Called on the way back. Absent means this step has no back control. */
  onBack?: () => void
  /** Called on the way out. Absent means the sequence cannot be skipped. */
  onDismiss?: () => void
  /** The forward control's text. */
  nextLabel?: string
  /** The back control's text. */
  backLabel?: string
  /** The way out's text. */
  dismissLabel?: string
  /** The word a player reads as the whole sequence's name. */
  label?: string
}

/** From the contract's table of state words, so no component invents its own. */
const STATE_WORD = {
  complete: 'complete',
  active: 'current',
} as const

/**
 * The pager, from the sequence's position: everything behind the player is
 * complete, the one they are on is active, the rest are still to come.
 *
 * Derived rather than passed, because the sequence's position is already in
 * `step`, and a second source for the same fact is how the pager ends up
 * disagreeing with the card above it.
 */
export function pagerSegments(total: number, step: number): Segment[] {
  return Array.from({ length: total }, (_, index) => {
    const position = index + 1
    if (position < step) return { state: 'complete' as const }
    if (position === step) return { state: 'active' as const }
    return { state: 'empty' as const }
  })
}

export function Onboarding({
  steps,
  step,
  complete = false,
  dismissed = false,
  onNext,
  onBack,
  onDismiss,
  nextLabel = 'Next',
  backLabel = 'Back',
  dismissLabel = 'Skip',
  label = 'getting started',
  className,
  ...rest
}: OnboardingProps) {
  const max = steps.length
  // Out of range is the host's business, not a crash. A sequence asked for step
  // seven of three renders nothing rather than throwing, and the attributes
  // still carry what it was asked for so the host can see what it did.
  const current = steps[step - 1]

  // The name carries the state, because a screen reader user gets no pager and
  // no card. Order: what it is, then where it is, then what is true about it.
  const words = [label, `step ${step} of ${max}`]
  if (complete) words.push(STATE_WORD.complete)

  // Everything the card shows, held aside so the dismissed case is one
  // expression rather than a fragment wedged into the middle of the tree.
  const content = (
    <>
    {current?.media ? (
      <div className="gs-onboarding__media" data-gs-scope="onboarding" data-gs-part="media" aria-hidden="true">
        {current.media}
      </div>
    ) : null}

    {current ? (
      // A real tutorial-step, keeping its own root marker per the nesting
      // rule, so a test can tell composition from a card written again here.
      // Its own actions are off: this sequence owns the way forward, because
      // the pager and the way out sit beside it and a second Next inside the
      // card would be two controls for one act.
      <TutorialStep
        className="gs-onboarding__step"
        step={step}
        max={max}
        title={current.title}
        active
      >
        {current.body}
      </TutorialStep>
    ) : null}

    <div className="gs-onboarding__footer">
      {/* The pager is segments in its pager treatment: the same row of cells
          as the round indicator and the quest's progress, not a third row of
          dots written here. */}
      <Segments
        className="gs-onboarding__pager"
        presentation="pager"
        label={label}
        segments={pagerSegments(max, step)}
        aria-hidden="true"
      />

      <div className="gs-onboarding__actions" data-gs-scope="onboarding" data-gs-part="actions">
        {onDismiss ? (
          <button
            type="button"
            className="gs-onboarding__dismiss gs-action-type gs-pressable"
            data-gs-scope="onboarding" data-gs-part="dismiss"
            onClick={onDismiss}
          >
            {dismissLabel}
          </button>
        ) : null}
        {onBack ? (
          <button
            type="button"
            className="gs-onboarding__back gs-action-type gs-pressable"
            data-gs-scope="onboarding" data-gs-part="decrement"
            onClick={onBack}
          >
            {backLabel}
          </button>
        ) : null}
        {onNext ? (
          <button
            type="button"
            className="gs-onboarding__next gs-action-type gs-pressable"
            data-gs-scope="onboarding" data-gs-part="increment"
            // The one filled control on the card is the primary action, and
            // saying so is what lets the theme's primary case reach it: arcade
            // shouts NEXT and keeps Skip and Back in sentence case.
            data-gs-variant="primary"
            data-gs-animates="motion"
            onClick={onNext}
          >
            {nextLabel}
          </button>
        ) : null}
      </div>
    </div>
    </>
  )

  return (
    <div
      {...rest}
      className={['gs-onboarding', className].filter(Boolean).join(' ')}
      data-gs-component="onboarding"
      data-gs-step={step}
      data-gs-max={max}
      data-gs-complete={complete ? 'true' : undefined}
      data-gs-dismissed={dismissed ? 'true' : undefined}
      role="group"
      aria-label={words.join(', ')}
      // Dismissal is a state rather than an unmount, so the element stays in
      // the DOM and stops being announced instead of disappearing from it.
      aria-hidden={dismissed ? 'true' : undefined}
    >
      {/* Nothing inside once it is dismissed. The root is what stays, so a test
          can tell "closed by the player" from "never rendered"; keeping the
          controls would leave focusable elements inside an aria-hidden subtree,
          which is a keyboard trap for exactly the player that rule is for. */}
      {dismissed ? null : content}
    </div>
  )
}

/* Onboarding. Every value comes from a token; nothing here is a literal colour,
   size, duration or typeface.

   Specimen 3g draws this card and design/twins/3g.json measures ours against
   it, part by part: the surface, the illustration slot, the title and the line
   under it, the pager, and the row with the way out and the way forward.

   The step is a tutorial-step and the pager is segments; both style themselves.
   What is here is the surface around them, the illustration slot and the three
   controls.

   The action typeface and the press gesture come from `.gs-action-type` and
   `.gs-pressable` in packages/tokens/primitives.css, which every control below
   carries. Re-declaring either here is how a theme reaches four controls and
   silently skips two, which has already happened once. */

/* A raised sheet on the surface colour, outlined, on the raised depth: the
   drawing's card is 22px round and padded 18, which the sheet radius and the
   4-step spacing give it within 2px. */
.gs-onboarding {
  display: grid;
  gap: var(--gs-space-inset);

  padding: var(--gs-space-4);
  max-width: 100%;

  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);
  box-shadow: var(--gs-depth-raised);
}

/* The illustration or animation slot. Inset, per the depth rule: it is a hole
   in the card that the host's own artwork sits in, and the dashed edge is what
   an empty one reads as rather than a broken image. The drawing draws the
   slot 120px tall; that is the height of the artwork the host puts in it, not
   a size this component owns, so there is only a floor here. */
.gs-onboarding__media {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: var(--gs-space-12);
  overflow: hidden;

  background: var(--gs-color-muted);
  border: var(--gs-stroke-hairline) dashed var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-flat);
}

/* The step carries its own surface, and two raised cards inside one another
   read as a mistake. So it sits flat inside this one, as one column: the
   drawing puts the title and the line under it edge to edge with the card's
   padding, and draws no counter, because the pager below is the counter. The
   parts are reached by their contract attributes rather than the step's class
   names, which a theme may change. */
.gs-onboarding__step {
  grid-template-columns: 1fr;
  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
}

.gs-onboarding__step > [data-gs-scope='tutorial-step'][data-gs-part='step'] {
  display: none;
}

.gs-onboarding__step > [data-gs-scope='tutorial-step'][data-gs-part='label'],
.gs-onboarding__step > [data-gs-scope='tutorial-step'][data-gs-part='body'] {
  grid-column: 1;
}

/* The pager sits above the controls, on its own row, as drawn. */
.gs-onboarding__footer {
  display: grid;
  gap: var(--gs-space-inset);
}

.gs-onboarding__pager {
  width: auto;
}

.gs-onboarding__actions {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
}

/* The three controls share everything but their fill. The drawing draws them
   52px tall; the touch minimum is the token nearest that height, and is the
   floor a hurried thumb needs on the way out of an onboarding anyway. */
.gs-onboarding__dismiss,
.gs-onboarding__back,
.gs-onboarding__next {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: var(--gs-size-touch-min);
  padding-inline: var(--gs-space-4);

  border-radius: var(--gs-radius-md);
  cursor: pointer;
}

/* The way forward is the one action on the surface, so it is the only filled
   one, and it takes the width the way out leaves: the drawing stretches it
   across the row. Outlined in edge like every arcade control. */
.gs-onboarding__next {
  flex: 1 1 0;
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  box-shadow: var(--gs-depth-pressable);
}

.gs-onboarding__next:hover {
  background: var(--gs-color-interactive-hover, var(--gs-color-interactive));
}

.gs-onboarding__back {
  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  box-shadow: var(--gs-depth-raised);
}

/* The way out is deliberately the quietest thing on the card: it is there for
   the player who wants it and it does not compete with the way forward. */
.gs-onboarding__dismiss {
  color: var(--gs-color-ink-secondary);
  background: transparent;
  border: none;
}

.gs-onboarding__dismiss:hover {
  color: var(--gs-color-ink);
}

.gs-onboarding__dismiss:focus-visible,
.gs-onboarding__back:focus-visible,
.gs-onboarding__next:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-selected);
  outline-offset: var(--gs-space-1);
}

/* -- dismissed ------------------------------------------------------------ */
/* Closed by the player, which is a state and not an unmount. The element stays
   so a test can tell it from "never rendered"; it renders nothing. */
.gs-onboarding[data-gs-dismissed='true'] {
  display: none;
}

/* Shared rule sets, so a theme axis reaches a component without the component
 * remembering to read it.
 *
 * The problem this solves, measured rather than predicted. Every theme axis used
 * to need every component to opt in by hand, one CSS property at a time, and
 * nothing detected a component that missed one. Four of the six stylesheets
 * using the action type read `--gs-type-action-text-transform` and two did not,
 * so the arcade theme's uppercase reached four controls and silently skipped
 * two. The press gesture was the same shape of problem across five files.
 *
 * At 25 components that is an afternoon of patching. At 45 it is a permanent tax
 * and a permanent source of themes that are half applied, because the failure is
 * always silent: a missing line looks exactly like a theme that chose not to
 * change anything.
 *
 * So the rules live once, here, and a component includes a class rather than
 * re-declaring six `var()` lines. A theme adding a seventh property to an axis
 * changes this file and reaches every component that already uses the class.
 *
 * This ships with `@gamestage/tokens`, which every component already depends on,
 * so including it costs a consumer nothing they were not already installing.
 */

@layer gs.primitives {
  /* Type for anything a player presses to act: buttons, choices, commits.
   * A theme that changes the action typeface, its weight or its casing reaches
   * every one of them through this rule alone. */
  .gs-action-type {
    font-family: var(--gs-type-action-font-family);
    font-size: var(--gs-type-action-font-size);
    font-weight: var(--gs-type-action-font-weight);
    letter-spacing: var(--gs-type-action-letter-spacing);
    text-transform: var(--gs-type-action-text-transform, none);
  }

  /* Type for a number a player reads at a glance: score, stat, rank, level,
   * timer. The theme owns the face, the weight and the shadow behind it.
   *
   * text-shadow is the axis that needed this. arcade has defined
   * type.displayShadow since the beginning, one component read it by name, and
   * the other seven numbers on screen had no shadow at all. Declared here it
   * reaches every number that carries the class.
   *
   * Family, size and weight are a floor rather than a ruling: a component
   * stylesheet is unlayered, so its own font-size beats this one whatever the
   * selector, and a stat stays 22px while a podium place stays 56px. If anyone
   * ever wraps packages/ui/src/*.css in a layer, that stops being true and
   * every number jumps to the display size. Wrap this file at the same time. */
  .gs-display-type {
    font-family: var(--gs-type-display-font-family);
    font-size: var(--gs-type-display-font-size);
    font-weight: var(--gs-type-display-font-weight);
    text-shadow: var(--gs-type-display-shadow, none);
  }

  /* Case is not the library's decision, and it is not only the theme's either.
   *
   * A theme sets the default: arcade uppercases its actions because a cabinet
   * marquee shouts, paper does not. A host overrules it anywhere, on the
   * document for the whole app, on a section, or on one component, by setting
   * data-gs-case. Nothing here is baked in and nothing needs a prop on
   * twenty-five components to reach.
   *
   *   <html data-gs-case="none">            every action in sentence case
   *   <section data-gs-case="upper">        this part shouts
   *
   * The precedent is worth naming. Material UI hardcoded uppercase into its
   * button and its tabs, and a decade of issues followed from people trying to
   * turn it off, because the only way out was overriding component internals.
   * shadcn has the opposite answer and it only works because you own the source:
   * case is a utility class in a file you can edit, and the theme layer carries
   * colour and radius and no typography at all. We are a registry, so a
   * consumer does own the component file, but they should not have to edit it
   * to answer a question this ordinary.
   *
   * These rules sit in gs.primitives, which is declared after gs.theme, so a
   * host always wins over a theme. */
  [data-gs-case='upper'] {
    --gs-type-action-text-transform: uppercase;
    --gs-type-action-text-transform-primary: uppercase;
  }
  [data-gs-case='none'] {
    --gs-type-action-text-transform: none;
    --gs-type-action-text-transform-primary: none;
  }

  /* The theme's loud face lands on the primary action and nowhere else.
   *
   * arcade shouts on the action a screen is built around and leaves the rest in
   * sentence case: options, nav destinations, dismiss links. This needed a
   * second typeface while arcade drew in Bungee, which has no lowercase glyphs
   * at all, so an option computed text-transform: none and still read EASY.
   * Arcade is back on the design's own face, which has lowercase, so one font
   * does both jobs and the rule below is only about case. The drawn design does not do that. It shouts one
   * word, the one the screen is built around, and keeps the rest in sentence
   * case, and a screen with everything uppercased reads as an error message
   * rather than a game.
   *
   * Primary means one of two things, both already in the markup: the element
   * carries data-gs-variant="primary", which is a button's default, or it is
   * the commit, the control that locks an answer in.
   *
   * A theme that says nothing about primary case gets the general one: the base
   * token is declared as an alias of it, so the two move together until a theme
   * separates them. A host setting data-gs-case wins over either, because those
   * rules set both custom properties. */
  .gs-action-type:is([data-gs-variant='primary'], [data-gs-part='commit']):not([data-gs-locked='true']) {
    text-transform: var(
      --gs-type-action-text-transform-primary,
      var(--gs-type-action-text-transform, none)
    );
  }

  /* A locked primary is not the action the screen is built around while it
   * cannot be pressed, so it does not shout: specimens 1f and 2b type "Level 8"
   * and "Lv 8" in sentence case beside an uppercase START. A disabled one keeps
   * its case: 4c draws VERIFY and ENTER in capitals while they wait for input,
   * because they are still the action, only not yet. */

  /* The press gesture. A theme picks the whole transform, so it may travel on an
   * offset base, scale, or not move at all and shift colour instead.
   *
   * The transition is deliberately the only timed part: a press is movement, so
   * reduced motion zeroes it. Fill, glyph and glow changes are emphasis and are
   * not governed here, because that is how a player who cannot see movement
   * still learns what happened. */
  .gs-pressable {
    /* `motion.press` is 80ms and linear: "press is instant, no easing on the
       way down" (specimen 4a's rules and the motion table in 3i). It was
       ease-out here, which is a curve the drawing gives nothing. */
    transition:
      transform var(--gs-motion-press) var(--gs-motion-ease-press),
      box-shadow var(--gs-motion-press) var(--gs-motion-ease-press);
  }

  .gs-pressable:active:not([aria-disabled='true']):not([data-gs-disabled='true']) {
    transform: var(--gs-press-transform);
    box-shadow: var(--gs-depth-pressable-pressed);
  }

  /* A control that is not available does not move when pressed. Stated here
   * rather than in each component, for the same reason as everything else in
   * this file. */
  .gs-pressable[aria-disabled='true']:active,
  .gs-pressable[data-gs-disabled='true']:active {
    transform: none;
  }

  /* The named button style, chosen by one token.
   *
   * A style query rather than a value substitution, for identity.css's reason:
   * depth.style holds a keyword, and `box-shadow: squeeze` is invalid and would
   * compute to nothing without saying so.
   *
   * Each block remaps the three tokens a pressable control already reads,
   * rather than declaring box-shadow and transform here. That is not a detour.
   * A component stylesheet is unlayered and therefore outranks everything in
   * this layer whatever the selector, so a box-shadow written here would lose
   * to `.gs-button[data-gs-variant='primary']` and never arrive on screen; and
   * the offset base belongs to the primary variant alone, so declaring it on
   * every .gs-pressable would put a coloured slab under the ghost buttons too.
   * Remapping reaches the declaration the component already makes, and only
   * where the component makes one.
   *
   * A theme may still take a bundle apart for a bespoke look: override
   * depth.styles.<style>.pressable, or the colour and stroke tokens the bundles
   * are composed from. Overriding depth.pressable itself still reaches anything
   * that is not a .gs-pressable, which is where the base's own composition
   * lives. */
  @container style(--gs-depth-style: offset) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-offset-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-offset-pressed);
      --gs-press-transform: var(--gs-depth-styles-offset-transform);
    }
  }

  @container style(--gs-depth-style: squeeze) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-squeeze-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-squeeze-pressed);
      --gs-press-transform: var(--gs-depth-styles-squeeze-transform);
    }
  }

  @container style(--gs-depth-style: glow) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-glow-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-glow-pressed);
      --gs-press-transform: var(--gs-depth-styles-glow-transform);
    }
  }

  /* Reduced motion, restated on the element and deliberately last.
   *
   * The build zeroes press.transform on :root, which reaches a control by
   * inheritance, and an element's own declaration beats an inherited value
   * whatever the layer. So the three blocks above would have handed every
   * pressable its theme's gesture back under prefers-reduced-motion, and the
   * default project in the browser matrix cannot see it. Same selector, same
   * specificity, same layer: source order decides, so this stays at the bottom.
   * The shadow still collapses to the pressed value, so the control answers the
   * tap without moving. */
  @media (prefers-reduced-motion: reduce) {
    .gs-pressable { --gs-press-transform: none; }
  }
}
